/bin/bash -lc "python - <<'PY'
import requests
for repo in ['biocontainers/statsmodels','biocontainers/openpyxl','biocontainers/r-readxl','biocontainers/r-base']:
    url=f'https://quay.io/api/v1/repository/{repo}/tag/'
    try:
        r=requests.get(url, params={'limit':20}, timeout=30)
        print('###', repo, r.status_code)
        if r.ok:
            tags=[t['name'] for t in r.json().get('tags', []) if not t.get('hidden')]
            for tag in tags[:10]: print(tag)
        else:
            print(r.text[:300])
    except Exception as e:
        print('ERR', repo, e)
PY"

